// Generated by owninfra generate. Do not edit: changes are overwritten and a hand edit makes generate refuse.
import { describe, expect, it } from "vitest";
import { getTableColumns, type Table } from "drizzle-orm";
import { authorize, createColumns, decideTransition, transitionInputProblems } from "./guard";
import { coerce, fromForm } from "./coerce";
import { registry } from "./registry";
import * as schema from "./schema";
import type { Row } from "./types";

const owner = "owner@example.test";
const other = "other@example.test";

describe.each(registry.entities.filter((e) => e.workflow))("$entity workflow", (entity) => {
  const wf = entity.workflow!;
  const row = (status: string, createdBy = owner): Row => ({
    id: "00000000-0000-0000-0000-000000000000",
    created_by: createdBy,
    [wf.field]: status,
  });

  it.each(wf.transitions.flatMap((t) => t.forbiddenFor.map((role) => [t.id, role] as const)))(
    "%s is forbidden for %s",
    (id, role) => {
      const t = wf.transitions.find((x) => x.id === id)!;
      const d = decideTransition({ email: other, roles: [role] }, entity, row(t.from), id);
      expect(d.ok).toBe(false);
    },
  );

  it.each(wf.transitions.map((t) => [t.id, t] as const))("%s succeeds for an allowed role", (_id, t) => {
    const actor = t.ownerOnly ? owner : other;
    const values = Object.fromEntries(t.requireFields.map((f) => [f, "because"]));
    const d = decideTransition({ email: actor, roles: [t.roles[0]] }, entity, row(t.from), t.id, {
      ...row(t.from),
      ...values,
    });
    expect(d).toMatchObject({ ok: true });
  });

  it.each(wf.transitions.filter((t) => t.forbidCreator).map((t) => [t.id, t] as const))(
    "%s is refused to the creator",
    (_id, t) => {
      const d = decideTransition({ email: owner, roles: [...t.roles] }, entity, row(t.from), t.id);
      expect(d).toMatchObject({ ok: false, status: 403 });
    },
  );

  it.each(wf.transitions.map((t) => [t.id, t] as const))("%s accepts only its require_fields", (_id, t) => {
    const other = entity.columns.map((c) => c.name).find((n) => !t.requireFields.includes(n))!;
    expect(transitionInputProblems(entity, t.id, Object.fromEntries(t.requireFields.map((f) => [f, "x"])))).toEqual([]);
    expect(transitionInputProblems(entity, t.id, { [other]: "x" })).toEqual([
      `field '${other}' cannot be set by '${t.id}'`,
    ]);
    expect(transitionInputProblems(entity, t.id, { [wf.field]: wf.states[wf.states.length - 1].id })).toHaveLength(1);
  });

  it("refuses a transition from the wrong state", () => {
    const t = wf.transitions[0];
    const wrong = wf.states.find((s) => s.id !== t.from)!.id;
    expect(decideTransition({ email: other, roles: [...registry.roles] }, entity, row(wrong), t.id)).toMatchObject({
      ok: false,
      status: 409,
    });
  });
});

describe("policies", () => {
  it.each(registry.policies.filter((p) => p.scope === "own").map((p) => [p.entity, p.role, p.action] as const))(
    "%s %s %s is limited to own rows",
    (name, role, action) => {
      const entity = registry.entities.find((e) => e.entity === name)!;
      const p = registry.policies.find((x) => x.entity === name && x.role === role && x.action === action)!;
      const status = p.inStates?.[0] ?? entity.workflow?.initial;
      const r = (createdBy: string): Row => ({
        id: "x",
        created_by: createdBy,
        ...(entity.workflow ? { [entity.workflow.field]: status } : {}),
      });
      expect(authorize({ email: owner, roles: [role] }, entity, action, r(owner))).toBe(true);
      expect(authorize({ email: owner, roles: [role] }, entity, action, r(other))).toBe(false);
    },
  );

  it("denies roles with no policy", () => {
    for (const entity of registry.entities) expect(authorize({ email: owner, roles: [] }, entity, "read")).toBe(false);
  });
});

describe("schema", () => {
  it("matches the registry columns", () => {
    for (const entity of registry.entities) {
      const table = (schema as unknown as Record<string, Table>)[entity.table];
      const names = Object.values(getTableColumns(table)).map((c) => c.name);
      const expected = [
        "id",
        ...entity.columns.map((c) => c.name),
        ...(entity.workflow ? [entity.workflow.field] : []),
        "created_at",
        "updated_at",
        "created_by",
      ];
      expect(names).toEqual(expected);
    }
  });

  it("reports every invalid field by name", () => {
    const entity = registry.entities[0];
    const r = coerce(entity, { nope: 1 }, "create");
    expect(r).toMatchObject({ ok: false, errors: { nope: "unknown field" } });
  });
});

describe("create input", () => {
  it.each(registry.entities.filter((e) => e.workflow).map((e) => [e.entity, e] as const))(
    "%s create omits transition-only fields",
    (_name, entity) => {
      const later = entity.workflow!.transitions.flatMap((t) => t.requireFields);
      const createable = createColumns(entity).map((c) => c.name);
      for (const f of later) {
        const c = entity.columns.find((x) => x.name === f)!;
        if (c.required) continue;
        expect(createable).not.toContain(f);
        expect(coerce(entity, { [f]: "x" }, "create")).toMatchObject({
          ok: false,
          errors: { [f]: "cannot be set when creating" },
        });
      }
    },
  );

  it.each(registry.entities.flatMap((e) => e.columns.map((c) => [`${e.entity}.${c.name}`, e, c] as const)))(
    "%s runs form input through its codec",
    (_n, entity, c) => {
      const form = new FormData();
      const r = coerce(entity, fromForm([c], form), "update");
      expect(r).toMatchObject({ ok: true });
      form.set(c.name, c.input === "bool" ? "on" : "\u0000not valid\u0000");
      const bad = coerce(entity, fromForm([c], form), "update");
      if (c.input === "bool") expect(bad).toMatchObject({ ok: true, values: { [c.name]: true } });
      else expect(bad).toMatchObject({ ok: false, errors: { [c.name]: expect.any(String) } });
    },
  );

  it.each(
    registry.entities.flatMap((e) =>
      e.columns
        .filter((c) => c.required && ["string", "text", "email"].includes(c.input))
        .map((c) => [`${e.entity}.${c.name}`, e, c] as const),
    ),
  )("%s rejects whitespace-only API and form input as required", (_n, entity, c) => {
    expect(coerce(entity, { [c.name]: "   " }, "update")).toMatchObject({
      ok: false,
      errors: { [c.name]: "is required" },
    });
    const form = new FormData();
    form.set(c.name, "   ");
    expect(coerce(entity, fromForm([c], form), "create")).toMatchObject({
      ok: false,
      errors: { [c.name]: "is required" },
    });
  });

  it("reads datetime-local input as UTC and integers as numbers", () => {
    const columns = registry.entities.flatMap((e) => e.columns);
    const dt = columns.find((c) => c.input === "datetime");
    const int = columns.find((c) => c.input === "int");
    const form = new FormData();
    if (dt) form.set(dt.name, "2026-01-01T10:30");
    if (int) form.set(int.name, "42");
    const out = fromForm(
      [dt, int].filter((c) => c !== undefined),
      form,
    );
    if (dt) expect(out[dt.name]).toBe("2026-01-01T10:30Z");
    if (int) expect(out[int.name]).toBe(42);
  });
});
